CHAINS=[{'chain': '东易-正式摘帽与分段走势', 'source': '1225429061', 'pages': [1, 3, 4], 'subject': '上市公司两类风险警示的正式撤销及实际交易端点', 'changed': '7月17日公告已获交易所审核同意，7月20日复牌并撤销两类风险警示；期初“尚待核准”这一待办可关闭。公告写明涨跌幅10%，不再把5月5%旧幅度沿用期后。', 'open': '正式摘帽不等于后来盈利持续改善。7月3日至停牌前已跌21.58%，摘帽首日相对上一成交日跌9.97%，此后至11月19日跌22.04%；整段跌幅不都归给摘帽。7月17日停牌无实际成交收盘，保留空值。'}, {'chain': '东易-半年到第三季度经营', 'source': '1225621034', 'pages': [1, 2, 3], 'subject': '2026H1、前三季累计、第三季度单季合并归母与现金分开', 'changed': '前三季营收5.49亿元、归母亏损4999.17万元、扣非亏损5203.08万元；第三季度单季归母亏损3685.67万元，较半年累计亏损1313.51万元进一步增加。前三季经营现金净流出2.40亿元。', 'open': '净资产仍正及正式摘帽，不能替代当期盈利和现金判断；单季经营现金流出1.25亿元是累计减半年推算，不当表中直接披露。季度未经审计，也不外推全年是否重新触发警示。', 'supporting': [{'source': '1225501314', 'pages': [1, 2], 'state': '半年归母亏损收窄但仍亏、现金净流出1.15亿元，不能把半年同比改善延伸成下半年转盈。'}]}, {'chain': '顾地-宁夏建工发回重审', 'source': '1225463181', 'pages': [1, 4], 'subject': '上市公司被追加执行人与已剥离梦想汽车的案件责任', 'changed': '8月公告撤销原一审判决并发回重审，二审受理费587784.99元应退；是程序重开，不是终局认定不承担责任或全部债务消除。', 'open': '9月同案表仍列发回重审，预计负债13586.08万元为未经审计财务测算，不因发回重审自动冲回。8月正文称8月5日收到，9月表称8月6日，日期冲突保留，未擅认笔误。', 'supporting': [{'source': '1225555470', 'pages': [9], 'state': '同案后续表保留发回重审与预计负债，收到日8月6日与8月原件8月5日不同。'}]}, {'chain': '顾地-精工案件与资产保全', 'source': '1225555470', 'pages': [4, 5], 'subject': '同一精工追加执行异议之诉的庭审与财产保全', 'changed': '7月13日已开庭，9月收到保全裁定与告知，查封厂区多处房产，查封期2026年9月3日至2029年9月2日；申请保全价值24235.78万元。', 'open': '3月发回重审是前置历史，不当9月新撤销判决。申请保全上限不是已实际冻结现金、已支付赔款或新增损失；原银行保全与新房产保全是否替换或重叠未核清，不直接相加。', 'continuity': [{'source': '1225411209', 'published_on': '2026-07-07', 'page': 4, 'stage': '披露收到7月13日庭前质证传票；重审源自3月裁定，不当7月首次免责'}, {'source': '1225555470', 'published_on': '2026-09-10', 'page': 5, 'stage': '重审期间新增房产查封，未证明案件已终局'}]}, {'chain': '顾地-追收未缴出资与银行冻结', 'source': '1225663133', 'pages': [1, 3, 4], 'subject': '原子公司已出表与上市公司被诉责任分别看', 'changed': '11月公告列追收未缴出资案尚未开庭，重排至11月27日；9月29日部分账户资金冻结17949833元。公司自查称原增资以1200万元债权认缴，与原告主张未货币实缴并列。', 'open': '原告诉请本金及利息17949833.33元不是法院已确认损失，冻结金额与诉请小数不同也保留；已剥离邯郸顾地不代表上市公司当然免责，期末之后开庭不预填结果。'}, {'chain': '顾地-上涨与经营现金压力', 'source': '1225641348', 'pages': [1, 2, 3], 'subject': '前三季累计与第三季度单季，不以价格替代财务', 'changed': '前三季营收增长13.22%，归母亏损同比收窄89%但仍亏3331.26万元；扣非亏损同比扩大64.76%，经营现金净流出1.58亿元、归母净资产仍负9607.87万元。第三季度单季归母亏损1482.10万元。', 'open': '营业外支出同比减少95.86%为当期诉讼预计负债计提较上期减少，不能写成所有旧预计负债转回、诉讼终局免责或现金已收。股价全段上涨37.66%不证明经营已修复，具体上涨原因仍未识别。', 'supporting': [{'source': '1225523850', 'pages': [1, 2], 'state': '半年归母亏损收窄而扣非亏损和现金流出扩大，负净资产仍在。'}]}, {'chain': '加加-赔偿债权与拍卖款的来源差异', 'source': '1225504556', 'pages': [28, 167, 168], 'subject': '赔偿款、库存拍卖所得款、账面减值及分类不同口径', 'changed': '半年报仍称未收到原实控人及关联方支付的委托加工损失赔偿款及利息；另确认库存原辅料已取回、拍卖变价款25040165.84元已收齐。损失赔偿款和拍卖款不是同笔回款。', 'open': '正文第28页称报告期不存在非经营性占用、往来表将相关损失承担款列经营性，与旧会计师说明称形成资金占用的分类不同；未见明确调节解释，不据此认证占用问题全部解决或选择会计最终真值。', 'supporting': [{'source': '1225504557', 'pages': [2], 'state': '两行分别列宁夏可可美与宁夏玉蜜余额3564.21万元且性质经营性；不按表格行数重复计算独立追偿或验证。'}]}, {'chain': '加加-半年盈利与单季转亏', 'source': '1225634661', 'pages': [1, 2], 'subject': '累计盈利、单季度盈利与实际经营现金分开', 'changed': '前三季归母盈利3651.31万元、扣非盈利2248.81万元、经营现金净流入2.33亿元；但第三季度单季归母亏损502.85万元、扣非亏损1012.60万元，不能把半年增长延伸为持续逐季改善。', 'open': '单季经营现金净流入268.15万元由累计减半年推算，明显低于半年累计不意味着同长同比骤降；未审计季度盈利与新审计解除旧保留、正式摘帽仍分别核。', 'supporting': [{'source': '1225504555', 'pages': [2], 'state': '半年归母盈利4154.16万元、扣非盈利3261.41万元及经营现金净流入2.30亿元；16项同比与季度桥接另有复算。'}]}, {'chain': '加加-原控股股东计划延期', 'source': '1225578143', 'pages': [2, 3], 'subject': '卓越投资破产重整，非上市公司本体', 'changed': '原控股股东卓越投资因投资人招募仍在进行，重整计划草案提交期限延至12月24日。公告称卓越投资为公司第二大股东、持19.55%，自身持股全部冻结或轮候冻结。', 'open': '这是股东的计划提交延期，不是上市公司新获重整受理、也不是上市公司获得新现金或控制权已变更。延期日不当完成日，具体投资人和股权变化仍待证据。'}, {'chain': '麦趣-清算申请撤回后再来', 'source': '1225552021', 'pages': [1, 2, 4], 'subject': '同一设备供应商铭慧机械与上市公司的债务程序', 'changed': '7月提示拟申请、8月债权人撤回、9月又披露申请，不能把8月撤回当债务已结清或风险永久关闭。9月仍称未收到法院法律文书，未认证已正式受理清算。', 'open': '9月列剩余货款4954900元，比7月5954900元少100万元；仅凭余额变化不认证特定日期付款、和解履约或全部清偿。公司认为不符合清算条件是发行人意见，不替代法院判断。', 'continuity': [{'source': '1225422339', 'published_on': '2026-07-14', 'page': 2, 'stage': '列剩余货款5954900元，提示债权人将申请，尚无法院受理裁定'}, {'source': '1225462121', 'published_on': '2026-08-07', 'page': 1, 'stage': '积极沟通和解、债权人自愿撤回，法院尚未受理；并非已结清'}, {'source': '1225552021', 'published_on': '2026-09-08', 'page': 2, 'stage': '再披露申请，仍无法院法律文书，剩余货款4954900元'}]}, {'chain': '麦趣-两次流拍不是处置回款', 'source': '1225510581', 'pages': [1], 'subject': '公司闲置机器设备的司法拍卖', 'changed': '8月披露四项闲置设备第一次、第二次拍卖均流拍；原“尚在公示”待办可更新为已披露两次无成交结果，不写成资产已售出、已收处置款。', 'open': '第二次结果原件两处写2025年8月25日，与8月18日预告2026年8月25日至26日及本件落款2026年8月27日不同。原日期并列保留，不擅认更正；流拍也不等于债务消失。', 'continuity': [{'source': '1225450939', 'published_on': '2026-08-01', 'page': 2, 'stage': '仅拟拍卖与公示，起拍价不当成交款'}, {'source': '1225478576', 'published_on': '2026-08-18', 'page': 1, 'stage': '首次流拍并预告2026年8月25日至26日二拍'}, {'source': '1225510581', 'published_on': '2026-08-27', 'page': 1, 'stage': '二拍仍流拍；两处2025年份冲突保留'}]}, {'chain': '麦趣-监管措施与整改', 'source': '1225526544', 'pages': [1, 2, 4], 'subject': '公司警示函与人员监管谈话，不混行政处罚', 'changed': '8月公司因诉讼、关联交易及失信事项未及时披露收到警示函，相关人员另受监管谈话，要求收到决定书30日内报整改。', 'open': '监管措施不写成行政处罚决定、正式摘帽核准或整改已验收。30日要求不当已提交，未取得整改报告或监管验收；重复人员与公司决定不增加独立案例数。'}, {'chain': '麦趣-单季亏损收窄与补助', 'source': '1225623265', 'pages': [1, 2, 3], 'subject': '第三季度单季与前三季累计、扣非及补助', 'changed': '第三季度归母亏损119.15万元，同比收窄96.56%，但扣非仍亏1635.16万元；单季计入非经常损益的政府补助1567.95万元，归母与扣非差1516.00万元，不把接近盈亏平衡当主业已转盈。', 'open': '前三季营收下降20.19%、归母亏损4772.46万元扩大44.22%；经营现金累计转为净流入258.48万元，但不关闭设备债务及清算申请待办。单季现金385.77万元是差额推算，未审计，不外推全年。', 'supporting': [{'source': '1225522498', 'pages': [2, 3], 'state': '半年亏损及现金流出分别核；同期基数有正有负，不混用改善比例。'}]}]
