STAGE_BINDING=[{'label': '期初至停牌前收盘', 'anchor': '2026-07-03', 'through': '2026-07-16', 'market_days': 9, 'stock_pct': '-21.57935887412040656763096169', 'market_pct': '-6.993576772032250906631064870', 'st_pct': '-4.957831856394961994400367760'}, {'label': '最后ST成交日至摘帽首日', 'anchor': '2026-07-16', 'through': '2026-07-20', 'market_days': 2, 'stock_pct': '-9.970089730807577268195413760', 'market_pct': '-5.336719281286697828253278190', 'st_pct': '-8.472118342500401479489298250'}, {'label': '摘帽首日收盘至截止日', 'anchor': '2026-07-20', 'through': '2026-11-19', 'market_days': 82, 'stock_pct': '-22.03765227021040974529346622', 'market_pct': '-13.50084753027984549265311188', 'st_pct': '-7.893412921663581444351140050'}, {'label': '期初完整段', 'anchor': '2026-07-03', 'through': '2026-11-19', 'market_days': 93, 'stock_pct': '-44.95699765441751368256450352', 'market_pct': '-23.84361043718606625351611964', 'st_pct': '-19.87640328334805222581559605'}]
def dongyi_stages(market,daily):
    prices={(r['symbol'],r['trade_date']):r for r in market['fixed_prices']}
    bench={(r['benchmark_id'],r['trade_date']):D(str(r['close']))for r in market['benchmarks']}
    rows=[]
    for spec in STAGE_BINDING:
        a,z=spec['anchor'],spec['through'];pa,pz=prices[('002713',a)],prices[('002713',z)]
        if not pa['has_trade']or not pz['has_trade']:raise ValueError('stage endpoint not traded')
        stock=(D(str(pz['close']))/D(str(pa['close']))-1)*100;market_pct=(bench[('csi_all_share',z)]/bench[('csi_all_share',a)]-1)*100;st=D(1);days=0
        for r in daily:
            if a<r['date']<=z:st*=1+D(str(r['return_pct']))/100;days+=1
        row=dict(label=spec['label'],anchor=a,through=z,market_days=days,stock_pct=str(stock),market_pct=str(market_pct),st_pct=str((st-1)*100))
        if row!=spec:raise ValueError('stage calculation changed')
        rows.append(row)
    if prices[('002713','2026-07-17')]['has_trade']:raise ValueError('stage halt changed')
    compound=D(1)
    for r in rows[:3]:compound*=1+D(r['stock_pct'])/100
    if abs((compound-1)*100-D(rows[-1]['stock_pct']))>D('1e-20'):raise ValueError('stage compound changed')
    return {'source':'1225429061','effective_on':'2026-07-20','halt_on':'2026-07-17','windows':rows,'boundary':'7月17日停牌，无实际成交收盘。首日段跨两个市场日，不当两个个股交易日；各段收益以复合相接，不直接相加。分段不识别公告或制度净因果。'}

def followup_view(inputs, prior):
    packet=inputs.get('ninth_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('period packet changed')
    if prior is None or prior['counts']['after']!=78 or packet['prior_digest']!=digest(prior):raise ValueError('period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=23 or len(packet['sources'])!=23 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid] or not s['protected_gate_passed']:raise ValueError('period source binding changed')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)} or len(s['page_hashes'])!=s['pages']:raise ValueError('period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('period page changed')
    for row in FINANCIAL:
        actual=((D(row['h1_yuan'])-D(row['prior_h1_yuan']))/abs(D(row['prior_h1_yuan']))*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if actual!=D(row['h1_yoy_pct']):raise ValueError('period H1 arithmetic changed')
        if D(row['nine_month_yuan'])-D(row['h1_yuan'])!=D(row['quarter_yuan']):raise ValueError('period quarter bridge changed')
        if row['reported_quarter_yuan'] is not None and D(row['quarter_yuan'])!=D(row['reported_quarter_yuan']):raise ValueError('period reported quarter changed')
        for aid,keys in [(row['h1_source'],['h1_yuan','prior_h1_yuan']),(row['q3_source'],['nine_month_yuan'])]:
            text=''.join(sources[aid]['selected_pages'].values()).replace(',','')
            if any(row[k]not in text for k in keys):raise ValueError('period financial source changed')
    from st_regime_comparison import build
    daily=build(market)['daily']
    windows=event_windows(market,daily,list(sources.values()),allow_nontraded=True)
    stages=dongyi_stages(market,daily)
    return {'through':'2026-11-19','title':'摘帽已完成，为什么经营和股价仍要另看？','answer':'东易7月已正式摘帽，期初等待核准的判断需要更新；但第三季度仍亏损、现金净流出，整段下跌也包含摘帽前的跌幅。顾地上涨同时仍有重审、保全及经营现金压力；加加累计盈利与单季转亏、赔偿债权与拍卖款分开；麦趣撤回后再申请、两次流拍和补助影响分别核。','chains':CHAINS,'financial_bridge':FINANCIAL,'dongyi_stages':stages,'event_windows':windows,'sources':[{k:v for k,v in s.items()if k not in ['raw_item','selected_pages','page_hashes']}for s in sources.values()],'counts':{'files':23,'pages':299,'viewed_pages':len(VISUAL),'initial_coverage':78,'complete_windows':sum(w['status']=='complete'for e in windows for w in e['windows']),'unfinished_windows':sum(w['status']=='unfinished'for e in windows for w in e['windows']),'stock_endpoint_gaps':sum(w['stock_pct']is None for e in windows for w in e['windows'])},'boundary':'23份299页中视觉核28关键页，其余未称逐页审阅；99条期间目录不认证所有渠道穷尽。期初覆盖保持78/150、仍缺72。审计分类、收到日期及拍卖年份差异未获明确更正，原表述并列保留。半年度与季度未经审计不当年度审计消除；4项单季经营现金由累计差额推算。停牌无实际成交端点保留空值。公告同窗与摘帽分段只描述过程，不能分摊公告或制度因果，重复文件不增加经验验证。','method_promotions':0}
